#pragma once
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

// The 3D world of a Blitz program: entities (pivots, cameras, lights and meshes) in a hierarchy.
//
// Blitz3D uses a left-handed coordinate system where +X is right, +Y is up and +Z is forward. Rotations are in
// degrees, and applied as roll (Z) first, then pitch (X), then yaw (Y).
//
// This part knows nothing about the GPU. graphics.cpp draws what is in here.

namespace bb {
	// A growable array for plain data, which avoids needing the C++ standard library in programs.
	template<typename T>
	struct buffer {
		T*       data = nullptr;
		uint32_t size = 0;
		uint32_t cap  = 0;

		T& operator[](uint32_t index) { return data[index]; }
		T const& operator[](uint32_t index) const { return data[index]; }

		void reserve(uint32_t count)
		{
			if (count > cap) {
				cap  = (cap ? cap * 2 : 16) > count ? (cap ? cap * 2 : 16) : count;
				data = static_cast<T*>(realloc(data, cap * sizeof(T)));
			}
		}

		void push(T const& value)
		{
			reserve(size + 1);
			data[size++] = value;
		}

		void clear() { size = 0; }

		void release()
		{
			free(data);
			data = nullptr;
			size = cap = 0;
		}
	};

	struct animation;
	struct skin_data;

	struct vertex3d {
		float   x, y, z;
		float   nx, ny, nz;
		float   u, v;
		uint8_t r, g, b, a;
	};

	// What a brush says about how something looks, and what a surface remembers of the brush it was painted with.
	struct material {
		float color[3]  = { 1, 1, 1 };
		float alpha     = 1;
		float shininess = 0;
		int   texture   = 0; // Handle, 0 for none.
		int   blend     = 0; // 0 = whatever the entity says.
		int   fx        = 0;
	};

	struct surface {
		skin_data* skin = nullptr; // If the vertices are moved by bones, which makes them different for each copy.
		bool     painted = false;
		material paint;

		buffer<vertex3d> vertices;
		buffer<uint32_t> indices;

		int refs = 1; // Copies of an entity share its surfaces.

		// Set by the renderer for its own use, and cleared whenever the geometry changes.
		bool dirty = true;
		void* gpu  = nullptr;
	};

	enum entity_kind { PIVOT = 0, CAMERA = 1, LIGHT = 2, MESH = 3 };

	// A heightmap that is drawn as a mesh. Heights go from 0 to 1.
	struct terrain_data {
		int    size   = 0; // Cells along each side, there is one more row of heights.
		float* heights = nullptr;
		bool   dirty  = true;
		bool   smooth = true;
	};

	struct entity {
		int         kind   = PIVOT;
		int         parent = 0; // Handle, 0 for none.
		bool        hidden = false;
		char*       name   = nullptr;

		float position[3] = { 0, 0, 0 };
		float rotation[3] = { 0, 0, 0 }; // Pitch, Yaw, Roll
		float scale[3]    = { 1, 1, 1 };

		// Appearance (meshes)
		float color[3] = { 1, 1, 1 };
		float alpha    = 1;
		int   fx       = 0; // 1 = fullbright, 16 = two-sided
		int   texture  = 0; // Handle, 0 for none.
		// Collisions and picking, see collision.cpp
		int   coll_type = 0;              // 0 = does not collide
		float radius[2] = { 0, 0 };       // Of the ellipsoid that collides, and of the sphere that is picked.
		bool  has_box   = false;
		float box[6]    = { 0, 0, 0, 0, 0, 0 }; // x, y, z, width, height, depth
		int   pick_mode = 0;              // 0 = can not be picked, 1 = sphere, 2 = polygons, 3 = box
		bool  pick_obscure = true;
		float old_pos[3]   = { 0, 0, 0 }; // Where it was at the last UpdateWorld.
		bool  old_valid    = false;

		int   sprite_mode = 0;           // 0 = not a sprite, 1 = faces the camera, 2 = fixed, 3 = free, 4 = upright
		float sprite_scale[2] = { 1, 1 };
		float sprite_angle    = 0;
		int   order    = 0; // Entities with a higher order are drawn first, and those with 0 are drawn normally.
		int   blend    = 1; // 1 = alpha, 2 = multiply, 3 = add
		float shininess = 0;
		float fade_near = 0, fade_far = 0; // Fades out between these distances to the camera, if far is not 0.
		buffer<surface*> surfaces;
		terrain_data*    terrain = nullptr;
		animation*       anim    = nullptr; // Of the top of an animated model, see animation.cpp

		// Camera
		float cam_near = 1, cam_far = 1000, cam_zoom = 1;
		float cam_color[3] = { 0, 0, 0 };
		bool  cam_clear_color = true, cam_clear_depth = true;
		int   cam_viewport[4] = { 0, 0, -1, -1 }; // Width and height of -1 use the whole buffer.
		int   cam_projection = 1; // 0 = disabled, 1 = perspective
		int   fog_mode = 0;       // 0 = off, 1 = linear
		float fog_near = 1, fog_far = 1000;
		float fog_color[3] = { 0, 0, 0 };

		// Light
		int   light_type = 1; // 1 = directional, 2 = point, 3 = spot (drawn as point)
		float light_color[3] = { 1, 1, 1 };
		float light_range    = 1000;
	};

	// Matrices are 4x4, column-major, for column vectors.
	void mat_identity(float* m);
	void mat_multiply(float* out, const float* a, const float* b);
	void mat_affine_inverse(const float* m, float* out);

	/** Highest entity handle in use. Handles start at 1. */
	int          entity_count();
	entity*      get_entity(int handle);
	void         world_matrix(int handle, float* out);
	extern float ambient_light[3];

	// For loading models (animation.cpp), which builds entities and surfaces itself.
	int       create_entity(int kind, int parent);
	surface*  create_surface(int mesh_handle);
	void      recalculate_normals(surface* s);
	void      euler_from_matrix(const float* m, float* euler);
	void      destroy_animation(animation* a);
	void      destroy_skin(skin_data* s);
	skin_data* clone_skin(skin_data const& s);
	// A copy of the animation for a copy of the model: pairs of what an entity was and is now.
	animation* clone_animation(animation const& a, buffer<int> const& was, buffer<int> const& now);

	/** Makes the mesh of a terrain match its heights, if they changed. */
	void update_terrain(entity& e);

	/** Calls the function for every visible entity of the given kind. */
	void         for_each_visible(int kind, void (*visit)(int handle, entity& e, void* user), void* user);
} // namespace bb
